#include <DHT.h>
#include <LiquidCrystal.h>

#define DHTPIN 2
#define DHTTYPE DHT22

DHT dht(DHTPIN, DHTTYPE);
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

void setup() {
    dht.begin();
    lcd.begin(16, 2);
}

void loop() {
    float t = dht.readTemperature();
    float h = dht.readHumidity();

    lcd.print("T: ");
    lcd.print(t);
    lcd.print("C H: ");
    lcd.print(h);
    lcd.print("%");
    delay(2000);
}

#include <Arduino.h>

#define SOIL_SENSOR A0
#define PUMP_PIN 8
#define FAN_PIN 9

void setup() {
    pinMode(PUMP_PIN, OUTPUT);
    pinMode(FAN_PIN, OUTPUT);
}

void loop() {
    int moisture = analogRead(SOIL_SENSOR);

    if (moisture < 500) {
        digitalWrite(PUMP_PIN, HIGH);
        delay(5000);
        digitalWrite(PUMP_PIN, LOW);
    }

    delay(1000);
}

#include <Arduino.h>
#include <SoftwareSerial.h>

#define PIR_PIN 2
#define SIRENE_PIN 8

SoftwareSerial gsm(10, 11);

void setup() {
    pinMode(PIR_PIN, INPUT);
    pinMode(SIRENE_PIN, OUTPUT);
    gsm.begin(9600);
}

void loop() {
    if (digitalRead(PIR_PIN) == HIGH) {
        digitalWrite(SIRENE_PIN, HIGH);
        gsm.println("AT+CMGS=\"+229XXXXXXXX\"");
        delay(1000);
        gsm.println("Intrusion detectee!");
        delay(5000);
        digitalWrite(SIRENE_PIN, LOW);
    }
}

#include <Arduino.h>

#define LEFT_SENSOR 2
#define RIGHT_SENSOR 3
#define LEFT_MOTOR 5
#define RIGHT_MOTOR 6

void setup() {
    pinMode(LEFT_SENSOR, INPUT);
    pinMode(RIGHT_SENSOR, INPUT);
    pinMode(LEFT_MOTOR, OUTPUT);
    pinMode(RIGHT_MOTOR, OUTPUT);
}

void loop() {
    if (digitalRead(LEFT_SENSOR) == LOW) {
        analogWrite(LEFT_MOTOR, 0);
        analogWrite(RIGHT_MOTOR, 200);
    } else if (digitalRead(RIGHT_SENSOR) == LOW) {
        analogWrite(LEFT_MOTOR, 200);
        analogWrite(RIGHT_MOTOR, 0);
    } else {
        analogWrite(LEFT_MOTOR, 200);
        analogWrite(RIGHT_MOTOR, 200);
    }
}

#include <WiFi.h>
#include <WebServer.h>

const char* ssid = "VotreWiFi";
const char* password = "VotreMotDePasse";

WebServer server(80);
#define RELAY_PIN 5

void setup() {
    WiFi.begin(ssid, password);
    pinMode(RELAY_PIN, OUTPUT);

    server.on("/", []() {
        server.send(200, "text/html", "<button onclick='fetch(\"/on\")'>ON</button>");
    });

    server.on("/on", []() {
        digitalWrite(RELAY_PIN, HIGH);
        server.send(200, "text/plain", "ON");
    });

    server.begin();
}

void loop() {
    server.handleClient();
}
